function loadHole(){
 clearFuseGraphics();lastAimKey='';lastAimTime=0;previewSequence++;
 const shared=new Set(Object.values(mats)),disposed=new Set();for(const c of [...course.children]){course.remove(c);c.traverse(o=>{if(o.geometry)o.geometry.dispose();if(o.material&&!shared.has(o.material)&&!disposed.has(o.material)){o.material.dispose();disposed.add(o.material);}});}trees=[];
 const h=holes[holeIndex];pin.set(h.pinX,elevation(h.pinX,-h.length,h),-h.length);setCupPosition(pin);
 const ground=mesh(new THREE.PlaneGeometry(368,850,64,128),mats.grass,course,-81,-.035,-220);ground.rotation.x=-Math.PI/2;ground.name='Coastal rough';conformSurface(ground,h);turf(ground,'rough',true,(x,z)=>terrain(x,z)==='rough'&&Math.abs(x-fairCenter(z)+32)>2);
 const seaMat=mats.water;disk(h.pond.x,h.pond.z,h.pond.rx+1.8,h.pond.rz+1.8,mats.sand,course,.028);water=disk(h.pond.x,h.pond.z,h.pond.rx,h.pond.rz,seaMat,course,.04);water.position.y=elevation(h.pond.x,h.pond.z,h)+.02;lakeSurface(water);
 const sea=mesh(new THREE.PlaneGeometry(700,1200),seaMat,course,455,-.4,-260);sea.rotation.x=-Math.PI/2;lakeSurface(sea,true);
 tube([new THREE.Vector3(99,-.06,100),new THREE.Vector3(107,-.06,-130),new THREE.Vector3(102,-.06,-350),new THREE.Vector3(110,-.06,-650)],4,mats.sand);
 // Fairway strips follow the curve and reveal a gentle mowing pattern.
 const vertices=[],uvs=[],indices=[],rows=128,cols=14;
 for(let i=0;i<=rows;i++){const z=8-i*(h.length+10)/rows,center=fairCenter(z),width=25+2*Math.sin(z*.047);for(let j=0;j<=cols;j++){const x=center-width+2*width*j/cols;vertices.push(x,.015,z);uvs.push(x/3,z/3);if(i<rows&&j<cols){const n=i*(cols+1)+j;indices.push(n,n+1,n+cols+1,n+1,n+cols+2,n+cols+1);}}}
 const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(vertices,3));geo.setAttribute('uv',new THREE.Float32BufferAttribute(uvs,2));geo.setIndex(indices);geo.computeVertexNormals();const fairway=mesh(geo,mats.fair.clone(),course);fairway.name='Fairway';conformSurface(fairway,h);turf(fairway,'fairway',true,(x,z)=>terrain(x,z)==='fairway');

 const fringe=mesh(ellipseGeometry(27,30),mats.fair.clone(),course,h.pinX,.02,-h.length);conformSurface(fringe,h);turf(fringe,'fringe');const green=mesh(ellipseGeometry(22,24),mats.green.clone(),course,h.pinX,.035,-h.length);conformSurface(green,h);puttingGrid(green,pin);
 for(const [x,z,rx,rz]of h.sand){conformSurface(disk(x,z,rx+1.2,rz+1.2,mats.fair,course,.05),h);const bunker=mesh(ellipseGeometry(rx,rz),mats.sand.clone(),course,x,.065,z);conformSurface(bunker,h);sandSurface(bunker);}
 disk(pin.x,pin.z,CUP_RADIUS,CUP_RADIUS,mat('#101812'),course,pin.y+GREEN_SURFACE_OFFSET-CUP_DEPTH);const cupRim=mesh(new THREE.RingGeometry(CUP_RADIUS,CUP_RADIUS+.015,48),mat('#dedaca'),course,pin.x,pin.y+GREEN_SURFACE_OFFSET+.003,pin.z);cupRim.rotation.x=-Math.PI/2;mesh(new THREE.CylinderGeometry(CUP_RADIUS,CUP_RADIUS,CUP_DEPTH,32,1,true),new THREE.MeshStandardMaterial({color:'#c5c0ae',roughness:1,side:THREE.BackSide}),course,pin.x,pin.y+GREEN_SURFACE_OFFSET-CUP_DEPTH/2,pin.z);mesh(new THREE.CylinderGeometry(.018,.018,6,8),mats.white,course,pin.x,pin.y+3,pin.z);flag=box(2,.95,.05,mat('#e2a36e'),course,pin.x+1,pin.y+5.45,pin.z);
 box(8,.08,5,mats.green,course,0,.04,2);for(const x of [-4,4])mesh(new THREE.SphereGeometry(.35,10,8),mats.white,course,x,.3,2);
 for(let i=0;i<76;i++){const side=i%2?1:-1;const z=20-(i/76)*(h.length+85),x=side*(40+((i*37)%54))+fairCenter(z);if(terrain(x,z)!=='water'){tree(x,z,i);course.children[course.children.length-1].position.y=elevation(x,z,h);}}
 batchForest(course,mats.trunk,mats.leaf);
 for(let i=0;i<19;i++){const rock=mesh(new THREE.DodecahedronGeometry(6+i%6,0),mat('#9d9e83'),course,94+(i%3)*3,-2,25-i*30);rock.scale.set(1,1.5,1.4);}
 landscape(course,h,fairCenter,terrain);for(const c of course.children){if(c.userData.surfaceDetail)conformSurface(c,h);}
 for(const c of course.children){if(c.isMesh&&c.geometry?.type==='PlaneGeometry')c.castShadow=false;}
 ballPos.set(0,.08+VISIBLE_BALL_RADIUS,0);personPos.set(-1.7,0,1.5);cartPos.set(-9,0,5);heading=0;speed=0;strokes=0;lastShot=null;power=.75;swingTime=0;shotShape=0;physicsAccumulator=0;engine.physics.freeze();club=holeIndex===1?2:0;aim=0;flight=null;complete=false;inCart=false;charging=false;person.visible=true;ball.visible=true;
 if(trail){scene.remove(trail);trail.geometry.dispose();trail.material.dispose();trail=null;}buildAim();updateUI();camera.position.set(18,16,30);$('result-dialog').hidden=true;toast('Hole '+(holeIndex+1)+' · '+h.name+'. Choose your club and let it fly.');
}
$('clubs').innerHTML=clubs.map((c,i)=>`<button data-club="${i}" title="${c[0]} · ${c[2]} yards">${c[1]}</button>`).join('');
$('shapes').onclick=e=>{if(e.target.dataset.shape===undefined||flight||charging)return;shotShape=+e.target.dataset.shape;buildAim();updateUI();};
$('clubs').onclick=e=>{if(e.target.dataset.club!==undefined)selectClub(+e.target.dataset.club);};
function selectClub(i){if(flight||charging||complete)return;club=i;buildAim();updateUI();}
function targetDistance(){let lie=terrain(ballPos.x,ballPos.z);return clubs[club][2]*power*(lie==='rough'?.83:lie==='bunker'?(club===4?.85:.5):1);}
function buildAim(){
 if(flight||complete)return;const now=performance.now(),key=[holeIndex,club,Math.round(power*20),aim.toFixed(2),ballPos.x.toFixed(1),ballPos.z.toFixed(1),shotShape].join(':');if(key===lastAimKey){previewDirty=false;return;}if(now-lastAimTime<(charging?180:70)){previewDirty=true;return;}previewDirty=false;lastAimKey=key;lastAimTime=now;
 const request={id:++previewSequence,h:holes[holeIndex],ball:ballPos.toArray(),pin:pin.toArray(),club,power,aim,shape:shotShape,puttDistance:puttRange(ballPos,pin)};
 if(previewWorker&&previewStats){if(previewBusy)previewQueued=request;else{previewBusy=true;previewWorker.postMessage(request);}}else{const prediction=predictor.preview(ballPos,pin,club,power,aim,shotShape,puttRange(ballPos,pin));displayPrediction(prediction,predictor.shot);}
}
function displayPrediction(prediction,shot){
 if(aimDots){scene.remove(aimDots);aimDots.geometry.dispose();aimDots.material.dispose();}if(landingRing){scene.remove(landingRing);landingRing.geometry.dispose();landingRing.material.dispose();}
 previewStats=prediction.stats;predictor.shot=shot;const positions=[];for(const p of prediction.points)positions.push(p.x,p.y+.13,p.z);const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));aimDots=new THREE.Points(g,new THREE.PointsMaterial({color:'#fffce2',size:.28,sizeAttenuation:true,transparent:true,opacity:.75}));scene.add(aimDots);landingRing=disk(prediction.end.x,prediction.end.z,.65,.65,new THREE.MeshBasicMaterial({color:'#ffedba',transparent:true,opacity:.55,depthWrite:false}),scene,prediction.end.y+.06);
}
if(previewWorker){previewWorker.onmessage=({data})=>{previewBusy=false;if(data.id===previewSequence&&!data.error&&!flight&&!complete)displayPrediction({points:data.points.map(p=>new THREE.Vector3(...p)),end:new THREE.Vector3(...data.end),stats:data.stats},data.shot);if(previewQueued){const next=previewQueued;previewQueued=null;previewBusy=true;previewWorker.postMessage(next);}};previewWorker.onerror=()=>{previewWorker.terminate();previewWorker=null;previewBusy=false;};}

function toast(message){$('toast').textContent=message;$('toast').style.opacity=1;toastTimer=performance.now()+6000;}
function updateUI(){document.querySelectorAll('[data-shape]').forEach(b=>b.classList.toggle('selected',+b.dataset.shape===shotShape));const stats=flight?engine.stats:lastShot;const launch=flight?.shot;const launchSpec=clubLaunches[club];$('telemetry-title').textContent=flight?'LIVE SHOT':lastShot?'LAST SHOT':'SHOT PREVIEW';$('telemetry-carry').textContent=Math.round(stats?.carry??previewStats?.carry??0);$('telemetry-roll').textContent=Math.round(stats?.roll??previewStats?.roll??0);$('telemetry-speed').textContent=Math.round(launch?.ballSpeed??lastShot?.ballSpeed??predictor.shot?.ballSpeed??0);$('telemetry-spin').textContent=Math.round(launch?.spinSpeed??lastShot?.spin??predictor.shot?.spinSpeed??launchSpec.spin);$('telemetry-apex').textContent=Math.round(stats?.apex??previewStats?.apex??0);const h=holes[holeIndex],distance=ballPos.distanceTo(pin),near=personPos.distanceTo(ballPos)<8,lie=terrain(ballPos.x,ballPos.z);$('hole').textContent=String(holeIndex+1).padStart(2,'0');$('par').textContent=h.par;$('hole-name').textContent=h.name;$('distance').innerHTML=Math.round(distance)+' <small>yd</small>';$('stroke').textContent=complete?strokes:strokes+1;const total=scores.reduce((sum,n,i)=>sum+n-holes[i].par,0);$('score').textContent=total===0?'E':total>0?'+'+total:total;$('club-name').textContent=clubs[club][0];$('carry').textContent=club===5?puttRange(ballPos,pin).toFixed(1):clubs[club][2];document.querySelector('.carry span').textContent=club===5?'YARDS · MAX PUTT':'YARDS · FULL SWING';document.querySelectorAll('[data-club]').forEach(b=>b.classList.toggle('selected',+b.dataset.club===club));$('aim-deg').textContent=Math.round(aim*180/Math.PI)+'°';$('power-text').textContent=Math.round(power*100)+'%';$('power-fill').style.width=power*100+'%';$('mode-label').textContent=inCart?'TAKING THE SCENIC ROUTE':flight?(flight.phase==='air'?'BALL IN FLIGHT':'BALL ROLLING'):near?'READY TO PLAY':'EXPLORE THE COURSE';$('mode-text').textContent=inCart?Math.round(Math.abs(speed)*2.2)+' mph · Golf cart':flight?(flight.phase==='air'?'Follow your shot':'Bounce & roll · '+Math.round(Math.hypot(flight.ground?.vx||0,flight.ground?.vz||0)*2.2)+' mph'):near?lie.charAt(0).toUpperCase()+lie.slice(1)+' lie':Math.round(personPos.distanceTo(ballPos))+' yd to your ball';$('mode-icon').textContent=inCart?'▰':'⚑';$('cart-button').innerHTML=inCart?'Exit cart <kbd>E</kbd>':'Drive cart <kbd>E</kbd>';$('swing').disabled=inCart||flight!==null||!near||complete;$('marker').style.display=flight||complete?'none':'block';$('shot-card').style.opacity=inCart?'.55':'1';document.querySelector('.map-card .eyebrow span').textContent=String(holeIndex+1).padStart(2,'0')+' / 03';}
function toggleCart(){if(flight||charging||complete)return;if(inCart){inCart=false;speed=0;personPos.copy(cartPos).add(new THREE.Vector3(2.7,0,0));person.visible=true;toast('Out of the cart. Walk to your ball to take a shot.');}else if(personPos.distanceTo(cartPos)<12){inCart=true;person.visible=true;toast('W / S accelerate & reverse · A / D steer · E hop out');}else toast('Walk to your cart first — '+Math.round(personPos.distanceTo(cartPos))+' yards away.');updateUI();}
function beginCharge(){if(paused||$('swing').disabled||charging)return;charging=true;chargeTime=0;power=.08;}
function releaseCharge(){if(!charging)return;charging=false;shoot();}
function shoot(){
 if(flight||inCart||complete||personPos.distanceTo(ballPos)>8)return;
 const from=ballPos.clone(),shot=engine.launch(ballPos,pin,club,power,aim,shotShape,puttRange(ballPos,pin));physicsAccumulator=0;
 flight={from,to:from.clone(),putt:club===5,phase:club===5?'ground':'air',points:[],last:from.clone(),carry:0,roll:0,ground:{vx:0,vz:0,bounces:0},shot};
 if(trail){scene.remove(trail);trail.geometry.dispose();trail.material.dispose();trail=null;}strokes++;swingTime=.7;aimDots.visible=false;person.rotation.y=-aim;toast(club===5?'Read the break. Let it roll.':'Pure contact. '+Math.round(shot.ballSpeed)+' mph · '+shot.spinSpeed.toFixed(0)+' rpm');updateUI();
}
function tickShot(dt){
 if(!flight)return;const f=flight,before=ballPos.clone();physicsAccumulator+=dt;
 while(physicsAccumulator>=1/120&&engine.active){engine.update(1/120);physicsAccumulator-=1/120;}
 const physical=engine.position();ballPos.copy(physical);ballPos.y+=VISIBLE_BALL_RADIUS-PHYSICS_BALL_RADIUS+BALL_SURFACE_OFFSET;f.phase=engine.phase;f.carry=engine.stats.carry;f.roll=engine.stats.roll;f.ground.bounces=engine.stats.bounces;
 const displacement=ballPos.clone().sub(before);f.ground.vx=displacement.x/Math.max(dt,.001);f.ground.vz=displacement.z/Math.max(dt,.001);
 if(engine.physics.isGrounded){const axis=new THREE.Vector3(displacement.z,0,-displacement.x);if(axis.lengthSq()>.000001)ball.quaternion.premultiply(new THREE.Quaternion().setFromAxisAngle(axis.normalize(),Math.hypot(displacement.x,displacement.z)/VISIBLE_BALL_RADIUS));}
 if(!engine.active){const end=engine.result;if(end?.isHoled){playAudio('holeout');sink();return;}finishShot();return;}
 if(engine.physics.isLanded&&['out','water'].includes(terrain(ballPos.x,ballPos.z))&&ballPos.y<elevation(ballPos.x,ballPos.z,holes[holeIndex])+.6){engine.physics.freeze();finishShot();return;}
 f.last.copy(ballPos);f.points.push(ballPos.clone());if(f.points.length>320)f.points.shift();if(!trail){trail=new THREE.Line(new THREE.BufferGeometry(),new THREE.LineBasicMaterial({color:'#fff6d5',transparent:true,opacity:.48}));scene.add(trail);}trail.geometry.dispose();trail.geometry=new THREE.BufferGeometry().setFromPoints(f.points);
}
const audio={};function playAudio(name){try{audio[name]??=new Audio(new URL('./assets/fuse/'+name+'.wav',import.meta.url));audio[name].currentTime=0;audio[name].volume=.25;audio[name].play().catch(()=>{});}catch{}}
engine.onLanding=()=>playAudio('thud');

function finishShot(){lastShot={carry:Math.round(flight.carry),roll:Math.round(flight.roll),bounces:flight.ground.bounces,apex:Math.round(engine.stats.apex),ballSpeed:Math.round(flight.shot.ballSpeed),spin:Math.round(flight.shot.spinSpeed)};const landing=terrain(ballPos.x,ballPos.z);if(landing==='water'||landing==='out'){ballPos.copy(flight.from);strokes++;toast(landing==='water'?'Splash! One penalty stroke. Play again from your last lie.':'Out of bounds. One penalty stroke; replay from your last lie.');}else{const dist=ballPos.distanceTo(pin);toast(Math.round(flight.carry)+' yd carry + '+Math.round(flight.roll)+' yd roll · '+Math.round(dist)+' yd to the pin.');if(dist<28)club=5;else if(dist<65)club=4;else if(dist<120)club=3;else if(dist<180)club=2;else club=1;}flight=null;power=.75;buildAim();updateUI();}
function sink(){complete=true;flight=null;ball.visible=false;aimDots.visible=false;scores[holeIndex]=strokes;const diff=strokes-holes[holeIndex].par;const labels={'-3':'Albatross!','-2':'Eagle!','-1':'Birdie!','0':'Par. Beautiful.','1':'Bogey.','2':'Double bogey.'};$('result-title').textContent=labels[diff]||'In the cup!';$('result-detail').textContent=holes[holeIndex].name+' · '+strokes+' strokes · Par '+holes[holeIndex].par;$('result-label').textContent=holeIndex===2?'ROUND COMPLETE':'HOLE '+(holeIndex+1)+' COMPLETE';$('scorecard').innerHTML=scores.map((s,i)=>'<div>HOLE 0'+(i+1)+'<b>'+s+'</b>PAR '+holes[i].par+'</div>').join('');$('next').textContent=holeIndex===2?'Play another round ↗':'Next hole ↗';$('result-dialog').hidden=false;updateUI();}
$('next').onclick=()=>{if(holeIndex===2){holeIndex=0;scores=[];}else holeIndex++;loadHole();};
$('cart-button').onclick=toggleCart;$('pin').onclick=()=>{aim=Math.atan2(pin.x-ballPos.x,ballPos.z-pin.z);buildAim();updateUI();};
for(const [id,delta]of [['aim-left',-.035],['aim-right',.035]])$(id).onclick=()=>{if(flight||charging)return;aim+=delta;buildAim();updateUI();};
$('swing').onpointerdown=e=>{e.preventDefault();$('swing').setPointerCapture(e.pointerId);beginCharge();};$('swing').onpointerup=releaseCharge;$('swing').onpointercancel=()=>{charging=false;power=.75;buildAim();};
$('help').onclick=()=>{paused=true;$('help-dialog').hidden=false;keys.clear();charging=false;};$('close-help').onclick=()=>{paused=false;$('help-dialog').hidden=true;};$('reset').onclick=()=>{holeIndex=0;scores=[];keys.clear();loadHole();};
window.addEventListener('keydown',e=>{if(['Space','ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.code))e.preventDefault();if(e.repeat){keys.add(e.code);return;}if(e.code==='Escape'){$('help-dialog').hidden=true;paused=false;}if(paused||complete)return;keys.add(e.code);if(e.code==='KeyE')toggleCart();if(/^Digit[1-6]$/.test(e.code))selectClub(+e.code.slice(-1)-1);if(e.code==='Space')beginCharge();});
window.addEventListener('keyup',e=>{keys.delete(e.code);if(e.code==='Space')releaseCharge();});window.addEventListener('blur',()=>{keys.clear();charging=false;});
// Touch movement is also available by dragging on the course.
let touchStart=null,touchMove={x:0,y:0};$('world').onpointerdown=e=>{if(e.pointerType==='mouse')return;touchStart={x:e.clientX,y:e.clientY};$('world').setPointerCapture(e.pointerId);};$('world').onpointermove=e=>{if(touchStart){touchMove.x=THREE.MathUtils.clamp((e.clientX-touchStart.x)/60,-1,1);touchMove.y=THREE.MathUtils.clamp((e.clientY-touchStart.y)/60,-1,1);}};$('world').onpointerup=$('world').onpointercancel=()=>{touchStart=null;touchMove={x:0,y:0};};
function canMove(x,z){const lie=terrain(x,z);if(lie==='water'||lie==='out')return false;return !trees.some(t=>Math.hypot(x-t.x,z-t.z)<1.5);}
function minimap(){const ctx=$('map').getContext('2d'),h=holes[holeIndex],w=220,height=245;ctx.clearRect(0,0,w,height);ctx.fillStyle='#e3e8d8';ctx.fillRect(0,0,w,height);const scale=205/(h.length+30),project=(x,z)=>[110+x*scale,225+z*scale];ctx.fillStyle='#bdd1c7';ctx.fillRect(110+103*scale,0,100,245);ctx.strokeStyle='#b6c88d';ctx.lineWidth=48*scale;ctx.lineCap='round';ctx.beginPath();for(let i=0;i<=40;i++){const z=-i*h.length/40,[x,y]=project(fairCenter(z),z);i?ctx.lineTo(x,y):ctx.moveTo(x,y);}ctx.stroke();let p=project(pin.x,pin.z);ctx.fillStyle='#a2bd76';ctx.beginPath();ctx.ellipse(...p,24*scale,24*scale,0,0,Math.PI*2);ctx.fill();p=project(h.pond.x,h.pond.z);ctx.fillStyle='#86b5b3';ctx.beginPath();ctx.ellipse(...p,h.pond.rx*scale,h.pond.rz*scale,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#dbc89d';for(const[x,z,rx,rz]of h.sand){p=project(x,z);ctx.beginPath();ctx.ellipse(...p,rx*scale,rz*scale,0,0,Math.PI*2);ctx.fill();}p=project(pin.x,pin.z);ctx.fillStyle='#214f3e';ctx.fillRect(p[0],p[1]-12,1,12);ctx.beginPath();ctx.moveTo(p[0],p[1]-12);ctx.lineTo(p[0]+8,p[1]-9);ctx.lineTo(p[0],p[1]-6);ctx.fill();for(const[pos,color,r]of [[cartPos,'#819480',3],[ballPos,'#c19557',3.5],[inCart?cartPos:personPos,'#214f3e',4]]){p=project(pos.x,pos.z);ctx.beginPath();ctx.arc(...p,r,0,Math.PI*2);ctx.fillStyle=color;ctx.fill();ctx.strokeStyle='#fffbed';ctx.lineWidth=1.5;ctx.stroke();}}
let uiTick=0;
function animate(time){requestAnimationFrame(animate);const frameMs=time-lastFrame,dt=Math.min(frameMs/1000,.1);lastFrame=time;frameBudget.update(time,frameMs);uiTick+=dt;if(previewDirty&&!flight&&!complete)buildAim();
 if(!paused&&!complete){
 if(charging){chargeTime+=dt;power=.08+.92*(.5-.5*Math.cos(chargeTime*2.8));$('power-fill').style.width=power*100+'%';$('power-text').textContent=Math.round(power*100)+'%';$('swing').innerHTML='Powering up… <span>Release to swing ↗</span>';buildAim();}else $('swing').innerHTML='Hold to power up <span>Release to swing ↗</span>';
 if(!flight&&!charging){const steerInput=(keys.has('KeyD')?1:0)-(keys.has('KeyA')?1:0)+touchMove.x,forward=(keys.has('KeyW')||keys.has('ArrowUp')?1:0)-(keys.has('KeyS')||keys.has('ArrowDown')?1:0)-touchMove.y;
 if(inCart){speed+=forward*16*dt;speed*=Math.exp(-dt*(forward?.35:2));speed=THREE.MathUtils.clamp(speed,-10,24);heading+=steerInput*dt*1.6*(speed<0?-1:1)*Math.min(Math.abs(speed)/4,1);const nx=cartPos.x+Math.sin(heading)*speed*dt,nz=cartPos.z-Math.cos(heading)*speed*dt;if(canMove(nx,nz))cartPos.set(nx,0,nz);else speed=-speed*.12;personPos.copy(cartPos);}else{const walkAngle=aim;const dx=(Math.sin(walkAngle)*forward+Math.cos(walkAngle)*steerInput)*dt*8,dz=(-Math.cos(walkAngle)*forward+Math.sin(walkAngle)*steerInput)*dt*8;if(canMove(personPos.x+dx,personPos.z+dz))personPos.add(new THREE.Vector3(dx,0,dz));if(dx||dz)person.rotation.y=Math.atan2(-dx,-dz);}
 if(keys.has('ArrowLeft')||keys.has('ArrowRight')){aim+=((keys.has('ArrowRight')?1:0)-(keys.has('ArrowLeft')?1:0))*dt*.5;buildAim();}
 }
 if(flight)tickShot(dt);
 }
 cartPos.y=elevation(cartPos.x,cartPos.z,holes[holeIndex]);personPos.y=elevation(personPos.x,personPos.z,holes[holeIndex]);cart.position.copy(cartPos);cart.rotation.y=-heading;person.position.copy(personPos);if(inCart){person.position.copy(cartPos).add(new THREE.Vector3(-.47,-.25,.4).applyAxisAngle(new THREE.Vector3(0,1,0),-heading));person.rotation.y=-heading;}golfer.club.visible=!inCart;ball.position.copy(ballPos);halo.position.set(ballPos.x,elevation(ballPos.x,ballPos.z,holes[holeIndex])+.1,ballPos.z);halo.visible=!flight&&!complete&&terrain(ballPos.x,ballPos.z)!=='green';ballShadow.position.set(ballPos.x,elevation(ballPos.x,ballPos.z,holes[holeIndex])+BALL_SURFACE_OFFSET+.002,ballPos.z);ballShadow.visible=!complete;ballShadow.scale.setScalar(1+Math.min(ballPos.y,30)*.08);ballShadow.material.opacity=Math.max(.05,.3-ballPos.y*.01);
 updateFuseGraphics(dt,camera,club===5&&!flight&&!inCart&&personPos.distanceTo(ballPos)<8);const moving=!inCart&&!flight&&(keys.has('KeyW')||keys.has('KeyS')||keys.has('KeyA')||keys.has('KeyD')||Math.abs(touchMove.x)+Math.abs(touchMove.y)>.1);walkTime+=dt*(moving?12:0);golfer.legs.forEach((leg,i)=>leg.rotation.x=inCart?1.1:moving?Math.sin(walkTime+i*Math.PI)*.45:0);swingTime=Math.max(0,swingTime-dt);golfer.arms.forEach((arm,i)=>{arm.rotation.x=inCart?.8:swingTime?Math.sin((.7-swingTime)*7)*-1.3:charging?-power*.9:moving?Math.sin(walkTime+i*Math.PI)*-.25:0;});golfer.club.rotation.x=swingTime?Math.sin((.7-swingTime)*7)*-1.8:charging?-power:0;cartModel.wheels.forEach(w=>w.rotation.x+=speed*dt/.43);
 const focus=flight?ballPos:inCart?cartPos:personPos;const angle=inCart?heading:aim;const cameraDistance=flight?.phase==='ground'?12:25;const cameraHeight=flight?.phase==='ground'?3.8:inCart?6.5:7.5;const camTarget=new THREE.Vector3(focus.x-Math.sin(angle)*cameraDistance,Math.max(0,focus.y)*.65+cameraHeight,focus.z+Math.cos(angle)*cameraDistance);camera.position.lerp(camTarget,1-Math.exp(-dt*3));const look=new THREE.Vector3(focus.x+Math.sin(angle)*10,flight?ballPos.y:2,focus.z-Math.cos(angle)*10);camera.lookAt(look);sun.target.position.set(focus.x,0,focus.z-20);sun.position.set(focus.x-55,95,focus.z+35);
 if(aimDots)aimDots.visible=!flight&&!inCart&&!complete;if(landingRing)landingRing.visible=!flight&&!inCart&&!complete;flag.rotation.z=Math.sin(time*.003)*.025;const screen=ballPos.clone().add(new THREE.Vector3(0,3,0)).project(camera);$('marker').style.left=(screen.x*.5+.5)*innerWidth+'px';$('marker').style.top=(-screen.y*.5+.5)*innerHeight+'px';$('marker').style.opacity=screen.z<1&&Math.abs(screen.x)<1?'1':'0';if(time>toastTimer)$('toast').style.opacity=0;
 if(uiTick>=.1){updateUI();minimap();$('fps').textContent=(frameBudget.fps||'–')+' FPS';uiTick=0;}renderer.render(scene,camera);
}
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);});
loadHole();$('loading').style.display='none';requestAnimationFrame(animate);
