window.fairway={snapshot:()=>({hole:holeIndex+1,strokes,club:clubs[club][0],inCart,ball:{x:ballPos.x,y:ballPos.y,z:ballPos.z},phase:flight?.phase||'rest',roll:flight?.roll||0,bounces:flight?.ground?.bounces||0,player:{x:personPos.x,z:personPos.z},flying:!!flight,complete,lastShot,performance:{...frameBudget.snapshot(),backend:renderer.backend.constructor.name,drawCalls:renderer.info.render.drawCalls,triangles:renderer.info.render.triangles,previewMode:previewWorker?'worker':'main'},engine:'OpenGolfSim Fuse',shotShape,prediction:previewStats,scores:[...scores]})};
